// Status only: never requests devices, invents tracking or changes saved media.
export function mediaWorkflow({kind,sourceKind,camera=false,mic=false,recording=false,tracked=0}){if(recording)return 'Recording your composed scene · stop recording before editing or leaving.';if(sourceKind==='photo')return 'Photo editor · choose lenses or layers, then SAVE TO GALLERY to keep an edited copy.';if(sourceKind==='video')return 'Video editor · trim and edit, then render and save your edited copy.';if(kind==='monster')return camera?`Live monster · ${tracked?'face detected':'waiting for a real face'} · ${mic?'microphone on':'microphone off'} · save your character before adding a voice.`:'Design your monster without a camera · enable the camera only when you want real face animation.';return camera?`Live camera · ${tracked?'face detected':'face tracking is waiting'} · ${mic?'microphone on':'microphone off'} · take a photo or record, then save to your local gallery.`:'Start with ENABLE CAMERA or OPEN PHOTO / VIDEO · devices remain off until you choose.';}
export function studioBadge(kind){return `<svg viewBox="0 0 80 64" aria-hidden="true"><rect x="6" y="13" width="68" height="44" rx="12" fill="#88aaa8" stroke="#294b57" stroke-width="3"/><path d="M20 13L26 6H45L50 13" fill="#d2be91" stroke="#294b57" stroke-width="3"/><circle cx="41" cy="35" r="16" fill="#e2dfc7" stroke="#294b57" stroke-width="3"/>${kind==='monster'?'<path d="M29 24L26 17L36 21M46 21L56 17L53 26" fill="#baa4c5" stroke="#294b57" stroke-width="2"/><circle cx="35" cy="34" r="2" fill="#294b57"/><circle cx="47" cy="34" r="2" fill="#294b57"/><path d="M34 41Q41 49 48 41" stroke="#294b57" stroke-width="3" fill="none"/>':'<circle cx="41" cy="35" r="9" fill="#466e7e"/><circle cx="38" cy="31" r="3" fill="#d0e4da"/>'}<circle cx="63" cy="22" r="3" fill="#d8be8a"/></svg>`;}
